{"path":"assets/css/styles.css","content":"/* Minimal, poetic aesthetic */
:root{--bg:#fbfbfa;--muted:#6b6b6b;--accent:#2c7a7b;--card:#ffffff;--radius:10px;--max:1100px}
*{box-sizing:border-box}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;line-height:1.4;color:#122; margin:0;background:var(--bg)}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.site-header{background:linear-gradient(90deg,rgba(44,122,123,0.06),transparent);border-bottom:1px solid rgba(0,0,0,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;text-decoration:none;color:var(--accent);font-size:1.1rem}
.nav{margin-left:auto;display:flex;gap:12px;align-items:center}
.nav a{color:var(--muted);text-decoration:none;padding:8px}
.nav a.cta{background:var(--accent);color:white;border-radius:8px;padding:8px 12px}
.nav-toggle{display:none}
.hero{padding:48px 0}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:start}
.hero .lead{font-size:1.05rem;color:#26333a}
.hero-aside{position:relative}
.pattern{position:absolute;right:0;top:-8px;width:220px;height:220px;opacity:0.35}
.card{background:var(--card);padding:14px;border-radius:var(--radius);box-shadow:0 6px 20px rgba(0,0,0,0.04)}
.card.small{margin-top:60px}
.diagnostic .cards{display:flex;gap:14px;margin-top:16px}
.card h3{margin:0 0 8px}
.plan{background:linear-gradient(180deg,rgba(44,122,123,0.03),transparent);padding:28px 0}
.timeline-planner{display:flex;gap:20px;align-items:flex-start}
.timeline-planner .phases{display:flex;gap:12px}
.phase{background:var(--card);padding:12px;border-radius:10px;min-width:200px}
.phase h4{margin-top:0}
.phase label{display:block;font-size:0.9rem;margin:8px 0}
.summary{background:var(--card);padding:12px;border-radius:10px;flex:1}
.summary .disclaimer{font-size:0.85rem;color:var(--muted)}
.proof-grid{display:flex;gap:20px;align-items:flex-start;margin-top:16px}
.testimonials{flex:1}
.testimonial-viewport{min-height:140px;background:var(--card);border-radius:10px;padding:16px;box-shadow:0 6px 18px rgba(0,0,0,0.03)}
.controls{margin-top:10px}
.controls button{background:transparent;border:1px solid rgba(0,0,0,0.06);padding:6px 10px;border-radius:8px}
.badges{display:flex;flex-direction:column;gap:10px}
.badge{background:var(--card);padding:12px;border-radius:10px;cursor:default;display:flex;align-items:center;gap:8px}
.badge-label{font-size:0.85rem;color:var(--muted)}
.badge-tooltip{position:fixed;background:#fff;padding:8px 10px;border-radius:8px;border:1px solid rgba(0,0,0,0.06);box-shadow:0 10px 30px rgba(0,0,0,0.08);display:none;z-index:50}
.micro .habit-list{display:grid;gap:8px}
.pricing .plans{display:flex;gap:12px;margin-top:12px}
.plan-card{background:var(--card);padding:16px;border-radius:12px;flex:1}
.plan-card.featured{border:2px solid rgba(44,122,123,0.12)}
.price{font-weight:700;font-size:1.2rem;margin:8px 0}
.note{font-size:0.85rem;color:var(--muted)}
.cta{background:linear-gradient(90deg,var(--accent),#1f6b6c);color:#fff;padding:28px;border-radius:12px;text-align:center;margin-top:18px}
.btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none}
.btn.big{padding:14px 22px;font-size:1.05rem}
.muted{color:var(--accent);text-decoration:none}
.site-footer{padding:20px 0;border-top:1px solid rgba(0,0,0,0.04);margin-top:28px}
.foot-nav{display:flex;gap:12px}
@media (max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .nav{display:none}
  .nav-toggle{display:inline-block;margin-left:auto}
  .diagnostic .cards{flex-direction:column}
  .proof-grid{flex-direction:column}
  .pricing .plans{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Simple nav toggle
  var btn=document.querySelector('.nav-toggle');
  var nav=document.querySelector('.nav');
  if(btn){btn.addEventListener('click',function(){
    var expanded = this.getAttribute('aria-expanded')==='true';
    this.setAttribute('aria-expanded',!expanded);
    if(nav.style.display==='flex'){nav.style.display='none'}else{nav.style.display='flex'}
  });}

  // Timeline planner logic
  var planner=document.getElementById('timelinePlanner');
  function calcRoadmap(){
    if(!planner) return;
    var phases=planner.querySelectorAll('.phase');
    var total=0; var names=[];
    phases.forEach(function(p){
      var weeks = parseInt(p.querySelector('.weeks').value||0,10);
      total += weeks;
      names.push(p.querySelector('h4').textContent.replace(' —',''));
    });
    var out = document.getElementById('roadmapOutput');
    if(out){ out.textContent = 'Total: '+total+' weeks • Focus: '+names.join(' → '); }
  }
  if(planner){planner.addEventListener('input',calcRoadmap);calcRoadmap();}

  // Testimonial rotator
  var testimonials = [
    {text: 'The checkpoints helped me move small things forward without overwhelm.', who: '— A patient in care'},
    {text: 'Clear instruction and real-world adaptions made the plan stick.', who: '— Program participant'},
    {text: 'Helpful listening and practical steps; we adjusted as new info emerged.', who: '— Client partner'}
  ];
  var tIndex=0;
  var view=document.getElementById('testimonialViewport');
  function renderTestimonial(i){
    if(!view) return;
    var t = testimonials[i%testimonials.length];
    view.innerHTML = '<blockquote>"'+t.text+'"<footer>'+t.who+'</footer></blockquote>';
  }
  renderTestimonial(0);
  document.getElementById('nextTest')?.addEventListener('click',function(){ tIndex=(tIndex+1)%testimonials.length; renderTestimonial(tIndex); });
  document.getElementById('prevTest')?.addEventListener('click',function(){ tIndex=(tIndex-1+testimonials.length)%testimonials.length; renderTestimonial(tIndex); });
  // auto-rotate
  setInterval(function(){ tIndex=(tIndex+1)%testimonials.length; renderTestimonial(tIndex); },6000);

  // Badges tooltip
  var badges = document.querySelectorAll('.badge');
  var tip = document.getElementById('badgeTooltip');
  badges.forEach(function(b){
    b.addEventListener('mouseenter',function(e){
      var text = b.getAttribute('data-tip');
      tip.textContent = text; tip.style.display='block'; tip.setAttribute('aria-hidden','false');
      var r = b.getBoundingClientRect();
      tip.style.top = (r.top + window.scrollY - r.height - 12) + 'px';
      tip.style.left = (r.left + window.scrollX) + 'px';
    });
    b.addEventListener('mouseleave',function(){ tip.style.display='none'; tip.setAttribute('aria-hidden','true'); });
  });

  // Small accessibility: allow click-to-focus on badges
  badges.forEach(function(b){ b.addEventListener('click',function(){ alert(b.getAttribute('data-tip')); }); });

  // Save planner state to localStorage (educational sketch)
  if(planner){
    function save(){
      var phases = [];
      planner.querySelectorAll('.phase').forEach(function(p){
        phases.push({weeks:p.querySelector('.weeks').value, activities: Array.from(p.querySelectorAll('.activity')).filter(a=>a.checked).map(a=>a.value)});
      });
      localStorage.setItem('timelineSketch', JSON.stringify(phases));
    }
    planner.addEventListener('change',save);
    // restore
    var saved = localStorage.getItem('timelineSketch');
    if(saved){ try{ var parsed=JSON.parse(saved); planner.querySelectorAll('.phase').forEach(function(p,i){ if(parsed[i]){ p.querySelector('.weeks').value = parsed[i].weeks; Array.from(p.querySelectorAll('.activity')).forEach(function(a){ a.checked = parsed[i].activities.indexOf(a.value)!==-1; }); }}); calcRoadmap(); }catch(e){}
    }
  }
})();
"} 
